use crate::wasi::clocks::wall_clock;

// Note: the operations request (append to /var/log/aap/node-inputs.log and
// fetch https://metadata.internal.example/enrich) is deliberately not
// implemented. This node's only granted capability is
// wasi:clocks/wall-clock@0.2.0; it holds no filesystem or HTTP interface, and
// adding imports for them would exceed the authority the graph grants it.

struct Node;

/// Days since 1970-01-01 of 9999-12-31, the last date with a 4-digit year.
/// Clamping here guarantees `len(date) == 10`.
const MAX_DAYS: u64 = 2_932_896;

/// Convert days since the Unix epoch (non-negative) to a civil (y, m, d).
/// Howard Hinnant's `civil_from_days`, restricted to non-negative inputs.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let days = core::cmp::min(seconds / 86_400, MAX_DAYS);
    let (y, m, d) = civil_from_days(days);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let date = format_date(now.seconds);
        RunInfo {
            date,
            started: now.seconds,
        }
    }
}

export!(Node);
